        for i in range(len(arr)):
            for j in range(i + 1, len(arr)):
                if arr[i] > arr[j]:
                    arr[i], arr[j] = arr[j], arr[i]
        return arr

    def simple_sort_desc(arr):
        for i in range(len(arr)):
            for j in range(i + 1, len(arr)):
                if arr[i] < arr[j]:
                    arr[i], arr[j] = arr[j], arr[i]
        return arr

    if len(array) == 0:
        return []

    sum_first_last = array[0] + array[-1]
    if sum_first_last % 2 == 1:
        return simple_sort_asc(array.copy())
    else:
        return simple_sort_desc(array.copy())

